package com.bank.payment;

import java.math.BigDecimal;
import java.util.logging.*;

public class PaymentDemo {
    private static final Logger log = Logger.getLogger("Payment");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountLedger ledger = new AccountLedger();
        ledger.open("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        ledger.open("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        PaymentService service = new PaymentService(ledger, new IdempotencyStore());

        BigDecimal rent = new BigDecimal("50000");

        // Authorize rent from Rajesh to Priya with an idempotency key
        PaymentResult r1 = service.authorize("idem-rent-oct", "SAV2001", "CUR3001", rent);
        log.info(() -> "Authorized paymentId=" + r1.paymentId());

        // Retry same key (network blink) → MUST NOT double-authorize
        PaymentResult r2 = service.authorize("idem-rent-oct", "SAV2001", "CUR3001", rent);
        log.info(() -> "Retry returned same paymentId=" + r2.paymentId()
            + " duplicate=" + r1.paymentId().equals(r2.paymentId()));

        // Capture the authorized payment
        service.capture(r1.paymentId());

        // Refund 10000 of it
        service.refund(r1.paymentId(), new BigDecimal("10000"));

        ledger.print(log);
    }
}

