package com.bank.payment;

import java.math.BigDecimal;

public class LedgerEntry {
    public enum Direction { DEBIT, CREDIT }
    private final String paymentId;
    private final String accountId;
    private final Direction direction;
    private final BigDecimal amount;
    private final String type;      // AUTH, CAPTURE, REFUND

    public LedgerEntry(String paymentId, String accountId, Direction direction,
                       BigDecimal amount, String type) {
            this.paymentId = paymentId;
            this.accountId = accountId;
            this.direction = direction;
            this.amount = amount
            this.type = type;
    }
    public BigDecimal signed() {
        return direction == Direction.CREDIT ? amount : amount.negate();
    }
    @Override public String toString() {
        return type + " " + direction + " " + accountId + " Rs." + amount + " (pay=" + paymentId + ")";
    }
}
